import{_ as a,o as i,c as l,ag as t}from"./chunks/framework.CxkNbRKf.js";const f=JSON.parse('{"title":"File manager","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/file-manager.md","filePath":"admin-guide/web-ui/file-manager.md","lastUpdated":1786379412000}'),s={name:"admin-guide/web-ui/file-manager.md"};function o(r,e,n,d,c,h){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="file-manager" tabindex="-1">File manager <a class="header-anchor" href="#file-manager" aria-label="Permalink to &quot;File manager&quot;">​</a></h1><p>The file manager provides access to the public file storage (<code>files/public</code>) where downloadable documents, images, and other resources are stored. Files uploaded here are publicly accessible from the catalog.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: File manager list view showing uploaded files with name, type, size, and date</em></p></div><h2 id="accessing-the-file-manager" tabindex="-1">Accessing the file manager <a class="header-anchor" href="#accessing-the-file-manager" aria-label="Permalink to &quot;Accessing the file manager&quot;">​</a></h2><p>Go to <strong>Settings → File manager</strong> in the administrator menu.</p><h2 id="browsing-files" tabindex="-1">Browsing files <a class="header-anchor" href="#browsing-files" aria-label="Permalink to &quot;Browsing files&quot;">​</a></h2><p>The file manager displays all files in the public filestore with their name, type, size, and upload date. Use the search box to filter by filename or type. Files can be sorted by name, date, or file type.</p><h2 id="uploading-files" tabindex="-1">Uploading files <a class="header-anchor" href="#uploading-files" aria-label="Permalink to &quot;Uploading files&quot;">​</a></h2><ol><li>Click <strong>Upload</strong>.</li><li>Select one or more files from your computer.</li><li>Upload progress is shown for each file.</li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: File upload dialog with progress indicator</em></p></div><p>Uploaded files are immediately available at their public URL.</p><h2 id="deleting-files" tabindex="-1">Deleting files <a class="header-anchor" href="#deleting-files" aria-label="Permalink to &quot;Deleting files&quot;">​</a></h2><p>Select one or more files using the checkboxes and click <strong>Delete</strong>, or use the delete icon on an individual file. Deleting a file removes it permanently from the server — ensure it is not referenced in any catalog entries before deleting.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Only files in the <code>files/public</code> directory are shown here. Files attached to catalog entries as study resources are managed through the catalog entry editor.</li><li>The file manager is intended for static assets such as documentation pages, site images, and similar shared resources.</li></ul>',15)])])}const g=a(s,[["render",o]]);export{f as __pageData,g as default};
